{
  "name": "magpie-local-services",
  "version": "0.2.1",
  "description": "Local services for magpie: run, supervise and update long-running local commands, and share local ports via Cloudflare quick tunnels",
  "homepage": "https://github.com/edifierx666/magpie-local-services#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/edifierx666/magpie-local-services.git"
  },
  "bugs": {
    "url": "https://github.com/edifierx666/magpie-local-services/issues"
  },
  "type": "module",
  "main": "./index.mjs",
  "files": [
    "index.mjs",
    "lib",
    "page",
    "web",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "services",
    "cloudflare-tunnel"
  ],
  "license": "MIT",
  "scripts": {
    "test": "bun test"
  },
  "engines": {
    "magpie": ">=0.1.1340"
  },
  "magpie": {
    "name": "本地服务",
    "icon": "https://raw.githubusercontent.com/edifierx666/magpie-local-services/main/assets/icon.png",
    "summary": {
      "en": "Run, supervise and update long-running local commands.",
      "zh": "运行、守护和更新长期运行的本地命令。"
    },
    "page": {
      "title": "Local Services",
      "titles": {
        "zh": "本地服务",
        "zh-TW": "本機服務"
      },
      "file": "page/index.html",
      "icon": "page/icon.svg",
      "service": {
        "port": 3427,
        "option": "port"
      }
    },
    "permissions": [],
    "options": {
      "port": 3427
    }
  }
}
